using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace SharpFFI.Generators.C;

[Generator(LanguageNames.CSharp)]
public class TestGenerator : IIncrementalGenerator
{
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(ctx =>
        {
            const string sourceCode = """
                                      // <auto-generated />
                                      using System;

                                      namespace SharpFFI
                                      {
                                          public static class GeneratorTest
                                          {
                                              public static void SayHello()
                                              {
                                                  Console.WriteLine("Hello from SharpFFI.Generators.C!");
                                              }
                                          }
                                      }
                                      """;

            ctx.AddSource("GeneratorTest.g.cs", SourceText.From(sourceCode, Encoding.UTF8));
        });
    }
}
